Here is the commit message:
staging: wilc1000: fix incorrect allocation size for
 structure

Currently the allocation for str_vals is for the sizeof the pointer
rather than the size of the structure.  Fix this.

Detected by smatch
"wilc_wlan_cfg_init() error: not allocating enough data 392 vs 8"

Fixes: acceb12a9f8b ("staging: wilc1000: refactor code to avoid static variables for config parameters")
Signed-off-by: Colin Ian King <colin.king@canonical.com>
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The bug was caused by incorrectly allocating memory for the `str_vals` variable using the size of the pointer instead of the size of the structure it points to. This resulted in insufficient memory being allocated, leading to potential memory corruption or access violations when the program attempted to use `str_vals`.

Here is the patch:

 int wilc_wlan_cfg_init(struct wilc *wl)
 {
 	struct wilc_cfg_str_vals *str_vals;
 	int i = 0;

 	wl->cfg.b = kmemdup(g_cfg_byte, sizeof(g_cfg_byte), GFP_KERNEL);
 	if (!wl->cfg.b)
 		return -ENOMEM;

 	wl->cfg.hw = kmemdup(g_cfg_hword, sizeof(g_cfg_hword), GFP_KERNEL);
 	if (!wl->cfg.hw)
 		goto out_b;

 	wl->cfg.w = kmemdup(g_cfg_word, sizeof(g_cfg_word), GFP_KERNEL);
 	if (!wl->cfg.w)
 		goto out_hw;

 	wl->cfg.s = kmemdup(g_cfg_str, sizeof(g_cfg_str), GFP_KERNEL);
 	if (!wl->cfg.s)
 		goto out_w;

-	str_vals = kzalloc(sizeof(str_vals), GFP_KERNEL);
+	str_vals = kzalloc(sizeof(*str_vals), GFP_KERNEL);
 	if (!str_vals)
 		goto out_s;

 	wl->cfg.str_vals = str_vals;
 	/* store the string cfg parameters */
 	wl->cfg.s[i].id = WID_FIRMWARE_VERSION;
 	wl->cfg.s[i].str = str_vals->firmware_version;
 	i++;
 	wl->cfg.s[i].id = WID_MAC_ADDR;
 	wl->cfg.s[i].str = str_vals->mac_address;
 	i++;
 	wl->cfg.s[i].id = WID_ASSOC_RES_INFO;
 	wl->cfg.s[i].str = str_vals->assoc_rsp;
 	i++;
 	wl->cfg.s[i].id = WID_NIL;
 	wl->cfg.s[i].str = NULL;
 	return 0;

 out_s:
 	kfree(wl->cfg.s);
 out_w:
 	kfree(wl->cfg.w);
 out_hw:
 	kfree(wl->cfg.hw);
 out_b:
 	kfree(wl->cfg.b);
 	return -ENOMEM;
 }



